SELECT tpd.TRADE_ID tradeId, bbs.BOOKSET_ID bookSetId, bbs.BOOKSET_NAME bookSetName, fpt.finprod_id subBookSetId, fpt.FINPROD_ABBR subBookSetName, tpd.TRADE_DATE payDate, tpd.MDATE feeEndDate, tfd.FEE_TYPE feeType, tfd.FEE_AMT payAmt, tfd.IS_PREPAID isNeedTan, tpd.IS_CLEAN isCountOver FROM bok_deal_accounting bdat INNER JOIN bok_deal_accounting_detail bdad ON bdat.busi_no = bdad.busi_no INNER JOIN trd_product_deal tpd on bdat.busi_no = tpd.TRADE_ID and tpd.ps in (#{PS_T10}) INNER JOIN TRD_TRADE_FEE_DETAIL tfd on tfd.TRADE_ID = tpd.TRADE_ID inner join bok_bookset bbs on bbs.BOOKSET_ID = bdat.BOOKSET_ID inner join fin_product fpt on fpt.finprod_id = tpd.FINPROD_ID WHERE 1=1
AND bbs.BOOKSET_ID = #{bookSetId,jdbcType=VARCHAR}
AND tfd.FEE_TYPE = #{feeType,jdbcType=VARCHAR}
AND tpd.TRADE_DATE = STR_TO_DATE(#{payDate,jdbcType=VARCHAR} , '%Y-%m-%d')

        select 
		    tmp.shouldPayAmt
		from (
		    select 
		        rank() over (partition by bbc.BOOKSET_ID,bbc.BOK_DETAIL_ID,bbc.BASE_SUBJECT_NATURE,bbc.BRANCH,bbc.O_CCY order by bbc.BOOK_ORDER desc) rk,
		        bbc.O_AMT_HAPPEN_DATE as shouldPayAmt
		    from 
		        BOK_BOOKDETAIL_CURRENT bbc
		        inner join bok_bookset bbs on bbc.bookset_id = bbs.bookset_id 

		    where
		        bbc.HAPPEN_DATE  <=  STR_TO_DATE(#{feeEndDate,jdbcType=VARCHAR}, '%Y-%m-%d')
		        and bbs.bookset_id = #{bookSetId,jdbcType=VARCHAR}

               	and bbc.BASE_SUBJECT_NATURE = #{baseSubjectNature,jdbcType=VARCHAR}


               	and bbc.BOK_DETAIL_ID = #{bokDetailId,jdbcType=VARCHAR}

		) tmp 
		where tmp.rk = 1

mapper.update:
update
	stl_orders 
set 
	SETTLE_AMT = #{feeAmt}
	,SETTLE_DATE = STR_TO_DATE(#{payDate}, '%Y-%m-%d') 
	,CCY = #{bccy}
where
	trade_id = #{tradeId}
